  );

  const updateStep = useCallback(
    async (stepId: string, payload: { name?: string; order?: number }) => {
      try {
        await apiUpdateStep(stepId, { ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Step updated.");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Could not update the step: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const deleteStep = useCallback(
    async (stepId: string) => {
      try {
        await apiDeleteStep(stepId, settings.mcp_url);
        pushToast("success", "Step removed.");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Could not remove the step: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const updateOutcome = useCallback(
    async (
      outcomeId: string,
      payload: { statement?: string; importance?: number; satisfaction?: number },
    ) => {
      try {
        await apiUpdateOutcome(outcomeId, { ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Outcome updated.");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Could not update the outcome: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const deleteOutcome = useCallback(
    async (outcomeId: string) => {
      try {
        await apiDeleteOutcome(outcomeId, settings.mcp_url);
        pushToast("success", "Outcome removed.");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Could not remove the outcome: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const closePanel = useCallback(() => setActivePanel(null), []);

  const openPanel = useCallback(
    (panel: WorkspacePanelId) => {
      if (setupOpen) {
        closeSetup();
      }
      setActivePanel(panel);
    },
    [setupOpen, closeSetup],
  );

  const stopStreaming = useCallback(() => {
    abortRef.current?.abort();
  }, []);

  const sendMessage = useCallback(
    async (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || streaming) {
        return;
      }

      const history: ChatMessage[] = [...messages, { role: "user", content: trimmed }];
      setMessages([...history, { role: "assistant", content: "", parts: [] }]);
      setStreaming(true);
      setThinkingPhase("health_check");
      setOfflineReply(false);
      setToolActivity([]);

      const controller = new AbortController();
      abortRef.current = controller;

      let content = "";
      let parts: ChatPart[] = [];

      // Prose is appended to the open text part; a surface opens a new one, so
      // the transcript keeps the agent's order instead of gathering all prose
      // above all cards.
      const appendText = (text: string) => {
        if (!text) {
          return;
        }
        content += text;
        const last = parts[parts.length - 1];
        parts =
          last?.kind === "text"
            ? [...parts.slice(0, -1), { kind: "text", text: last.text + text }]
            : [...parts, { kind: "text", text }];
      };

      const publish = () => {
        setMessages((prev) => {
          const next = [...prev];
          next[next.length - 1] = { role: "assistant", content, parts: [...parts] };
          return next;
        });
      };

      const handleEvent = (event: RawSseEvent) => {
        switch (event.event) {
          case "status": {
            const phase = String(event.data.phase ?? "");
            setThinkingPhase(phase);
            if (phase === "offline") {
              setOfflineReply(true);
            }
            break;
          }
          case "delta": {
            appendText(String(event.data.text ?? ""));
            publish();
            break;
          }
          case "ui": {
            // Validate again on arrival: the connection is local but the
            // renderer must never trust a shape it has not checked.
            const parsed = parseUiSpec(event.data.spec, catalogManifest());
            if (parsed.ok) {
              parts = [
                ...parts,
                { kind: "ui", id: String(event.data.id ?? `ui-${parts.length}`), node: parsed.node },
              ];
              publish();
            }
            break;
          }
          case "tool":
            setToolActivity((prev) => [
              ...prev,
              {
                name: String(event.data.name ?? ""),
                status: String(event.data.status ?? ""),
                preview: event.data.preview ? String(event.data.preview) : undefined,
              },
            ]);
            break;
          case "message": {
            content = String(event.data.content ?? content);
            const hasSurfaces = parts.some((part) => part.kind === "ui");
            if (!hasSurfaces) {
              parts = content ? [{ kind: "text", text: content }] : [];
            }
            publish();
            break;
          }
          case "canvas_dirty":
            void refreshCanvas();
            break;
          case "connector":
            setConnectorSuggestions((prev) => {
              const id = String(event.data?.preset ?? event.data?.name ?? "");
              if (!id || prev.includes(id)) {
                return prev;
              }
              return [...prev, id];
            });
            break;
          case "error":
            pushToast("error", String(event.data.message ?? "Unknown chat error"));
            break;
          default:
            break;
        }
      };

      try {
        await streamChat(
          {
            base_url: settings.base_url,
            api_key: settings.api_key,
            model: settings.model_name,
            mcp_url: settings.mcp_url,
            messages: history,
            brief,
            ui_catalog: catalogManifest(),
          },
          handleEvent,
          controller.signal,
        );
      } catch (error) {
        const aborted = (error as Error).name === "AbortError";
        if (!aborted) {
          pushToast("error", `Error during assistant completion: ${(error as Error).message}`);
        }
        if (!content) {
          setMessages((prev) => {
            const next = [...prev];
            if (next.length && next[next.length - 1].content === "") {
              next.pop();
            }
            return next;
          });
        }
      } finally {
        setStreaming(false);
        setThinkingPhase(null);
        abortRef.current = null;
      }
    },
    [messages, streaming, settings, brief, refreshCanvas, pushToast],
  );

  /** The single conversational exit from any lens. */
  const ask = useCallback(
    (intent: string) => {
      setActivePanel(null);
      void sendMessage(intent);
    },
    [sendMessage],
  );

  const clearChat = useCallback(() => {
    abortRef.current?.abort();
    abortRef.current = null;
    setMessages([]);
    setToolActivity([]);
    setStreaming(false);
    setThinkingPhase(null);
    setOfflineReply(false);
  }, []);

  // Initial hydration: env defaults, canvas, health probes.
  useEffect(() => {
    let cancelled = false;

    async function boot() {
      try {
        const defaults = await fetchConfig();
        if (!cancelled) {
          setSidecarReachable(true);
          if (localStorage.getItem(SETTINGS_KEY) === null) {
            saveSettings(defaults);
          }
        }
      } catch {
        if (!cancelled) {
          setSidecarReachable(false);
        }
      }
      if (cancelled) {
        return;
      }
      void refreshCanvas();
      void refreshConnectors();
      void refreshPresets();
      void healthMcp(settings.mcp_url)
        .then((result) => {
          if (!cancelled) {
            setMcpReachable(result.reachable);
          }
        })
        .catch(() => undefined);
      void healthLlm({
        base_url: settings.base_url,
        api_key: settings.api_key,
        model: settings.model_name,
      })
        .then((result) => {
          if (!cancelled) {
            setLlmHealth(result);
          }
        })
        .catch(() => undefined);
    }

    void boot();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const value = useMemo<StudioContextValue>(
    () => ({
      settings,
      saveSettings,
      displayName,
      setDisplayName,
      brief,
      saveBrief,
      setupOpen,
      openSetup,
      closeSetup,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      stopStreaming,
      clearChat,
      pushNotice,
      offlineReply,
      addStep,
      addOutcome,
      createJob,
      updateJob,
      deleteJob,
      updateStep,
      deleteStep,
      updateOutcome,
      deleteOutcome,
      activePanel,
      openPanel,
      closePanel,
      ask,
      toasts,
      pushToast,
      dismissToast,
      connectors,
      presets,
      refreshConnectors,
      refreshPresets,
      addConnector,
      deleteConnector,
      connectorSuggestions,
      dismissConnectorSuggestion,
      notifications,
      unreadNotificationCount,
      markNotificationAsRead,
      markAllNotificationsAsRead,
      dismissNotification,
      addNotification,
      simulateBackgroundEvent,
    }),
    [
      settings,
      saveSettings,
      displayName,
      setDisplayName,
      brief,
      saveBrief,
      setupOpen,
      openSetup,
      closeSetup,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      stopStreaming,
      clearChat,
      pushNotice,
      offlineReply,
      addStep,
      addOutcome,
      createJob,
      updateJob,
      deleteJob,
      updateStep,
      deleteStep,
      updateOutcome,
      deleteOutcome,
      activePanel,
      openPanel,
      closePanel,
      ask,
      toasts,
      pushToast,
      dismissToast,
      connectors,
      presets,
      refreshConnectors,
      refreshPresets,
      addConnector,
      deleteConnector,
      connectorSuggestions,
      dismissConnectorSuggestion,
      notifications,
      unreadNotificationCount,
      markNotificationAsRead,
      markAllNotificationsAsRead,
      dismissNotification,
      addNotification,
      simulateBackgroundEvent,
    ],
  );

  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
}

export function useStudio(): StudioContextValue {
  const context = useContext(StudioContext);
  if (!context) {
    throw new Error("useStudio must be used within a StudioProvider");
  }
  return context;
}

/**
 * The wire contract for agent-composed UI.
 *
 * A payload is a tree of `{ type, props, children }` nodes validated against a
 * catalog manifest. The manifest is plain JSON Schema (draft 2020-12 subset),
 * so the same document can be handed to the model as a tool schema and used
 * here to validate what comes back. Nothing is eval'd, no HTML is injected, and
 * every node is bounded before it can reach React.
 *
 * Parsing is deliberately forgiving where it is safe (unknown props are
 * stripped, unknown component types degrade to a visible fallback) and strict
 * where it matters (structure, required props, and size ceilings).
 */

export const UI_LIMITS = {
  maxDepth: 12,
  maxNodes: 200,
  maxStringLength: 2000,
  maxChildren: 32,
  maxActions: 40,
} as const;

/** A JSON Schema subset: enough to describe every prop in the catalog. */
export interface UiPropSchema {
  type?: "string" | "number" | "integer" | "boolean" | "array" | "object";
  description?: string;
  enum?: readonly string[];
  minimum?: number;
  maximum?: number;
  items?: UiPropSchema;
  properties?: Record<string, UiPropSchema>;
  required?: readonly string[];
  minItems?: number;
  maxItems?: number;
}

export interface UiCatalogEntry {
  type: string;
  kind: "layout" | "leaf";
  description: string;
  acceptsChildren: boolean;
  props: UiPropSchema;
}

export interface UiCatalogManifest {
  version: 1;
  components: UiCatalogEntry[];
}

export interface UiNode {
  type: string;
  props: Record<string, unknown>;
  children: UiNode[];
  /** Set when the manifest has no component for this type. */
  unsupported?: boolean;
}

export type ParseResult = { ok: true; node: UiNode } | { ok: false; reason: string };

type ValueResult = { ok: true; value: unknown } | { ok: false };

interface ParseState {
  entries: Map<string, UiCatalogEntry>;
  nodes: number;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function catalogIndex(manifest: UiCatalogManifest): Map<string, UiCatalogEntry> {
  return new Map(manifest.components.map((entry) => [entry.type, entry]));
}

function ok(value: unknown): ValueResult {
  return { ok: true, value };
}

const INVALID: ValueResult = { ok: false };

function validateValue(raw: unknown, schema: UiPropSchema, depth: number): ValueResult {
  if (depth > UI_LIMITS.maxDepth + 4) {
    return INVALID;
  }

  if (schema.enum) {
    return typeof raw === "string" && schema.enum.includes(raw) ? ok(raw) : INVALID;
  }

  switch (schema.type) {
    case "string":
      if (typeof raw !== "string" || raw.length > UI_LIMITS.maxStringLength) {
        return INVALID;
      }
      return ok(raw);

    case "number":
    case "integer": {
      if (typeof raw !== "number" || !Number.isFinite(raw)) {
        return INVALID;
      }
      if (schema.type === "integer" && !Number.isInteger(raw)) {
        return INVALID;
      }
      if (schema.minimum !== undefined && raw < schema.minimum) {
        return INVALID;
      }
      if (schema.maximum !== undefined && raw > schema.maximum) {
        return INVALID;
      }
      return ok(raw);
    }

    case "boolean":
      return typeof raw === "boolean" ? ok(raw) : INVALID;

    case "array": {
      if (!Array.isArray(raw)) {
        return INVALID;
      }
      if (schema.minItems !== undefined && raw.length < schema.minItems) {
        return INVALID;
      }
      if (schema.maxItems !== undefined && raw.length > schema.maxItems) {
        return INVALID;
      }
      const items: unknown[] = [];
      for (const entry of raw) {
        const validated = schema.items ? validateValue(entry, schema.items, depth + 1) : ok(entry);
        if (!validated.ok) {
          return INVALID;
        }
        items.push(validated.value);
      }
      return ok(items);
    }

    case "object": {
      if (!isPlainObject(raw)) {
        return INVALID;
      }
      const result = validateProps(raw, schema, depth + 1);
      return result.ok ? ok(result.value) : INVALID;
    }

    default:
      return INVALID;
  }
}

function validateProps(
  raw: Record<string, unknown>,
  schema: UiPropSchema,
  depth: number,
): { ok: true; value: Record<string, unknown> } | { ok: false } {
  const properties = schema.properties ?? {};
  const result: Record<string, unknown> = {};

  for (const key of schema.required ?? []) {
    if (!(key in raw)) {
      return { ok: false };
    }
  }

  for (const [key, value] of Object.entries(raw)) {
    const propertySchema = properties[key];
    if (!propertySchema) {
      // Unknown props are stripped rather than trusted.
      continue;
    }
    const validated = validateValue(value, propertySchema, depth);
    if (!validated.ok) {
      if ((schema.required ?? []).includes(key)) {
        return { ok: false };
      }
      continue;
    }
    result[key] = validated.value;
  }

  return { ok: true, value: result };
}

function describePropFailure(entry: UiCatalogEntry, key: string): string {
  const schema = entry.props.properties?.[key];
  if (!schema) {
    return `unknown prop "${key}"`;
  }
  if (schema.enum) {
    return `prop "${key}" must be one of ${schema.enum.join(", ")}`;
  }
  if (schema.type === "number" || schema.type === "integer") {
    const bounds =
      schema.minimum !== undefined || schema.maximum !== undefined
        ? ` between ${schema.minimum ?? "-∞"} and ${schema.maximum ?? "∞"}`
        : "";
    return `prop "${key}" must be a ${schema.type}${bounds}`;
  }
  if (schema.type === "array") {
    return `prop "${key}" must be an array of valid items`;
  }
  if (schema.type === "object") {
    return `prop "${key}" must be an object with the documented fields`;
  }
  if (schema.type === "boolean") {
    return `prop "${key}" must be a boolean`;
  }
  return `prop "${key}" must be a ${schema.type ?? "valid value"}`;
}

function parseNode(raw: unknown, depth: number, state: ParseState): ParseResult {
  if (depth > UI_LIMITS.maxDepth) {
    return { ok: false, reason: `UI tree exceeds the maximum depth of ${UI_LIMITS.maxDepth}` };
  }
  state.nodes += 1;
  if (state.nodes > UI_LIMITS.maxNodes) {
    return { ok: false, reason: `UI tree exceeds the maximum of ${UI_LIMITS.maxNodes} nodes` };
  }

  if (!isPlainObject(raw)) {
    return { ok: false, reason: "UI node must be an object" };
  }

  const type = raw.type;
  if (typeof type !== "string" || type.trim() === "" || type.length > 100) {
    return { ok: false, reason: "UI node needs a component type" };
  }

  if (raw.props !== undefined && !isPlainObject(raw.props)) {
    return { ok: false, reason: `UI node "${type}" has non-object props` };
  }
  if (raw.children !== undefined && !Array.isArray(raw.children)) {
    return { ok: false, reason: `UI node "${type}" has non-array children` };
  }

  const entry = state.entries.get(type);
  if (!entry) {
    return { ok: true, node: { type, props: {}, children: [], unsupported: true } };
  }

  const props = validateProps(isPlainObject(raw.props) ? raw.props : {}, entry.props, 0);
  if (!props.ok) {
    const failed = Object.keys(entry.props.properties ?? {}).find((key) => {
      const schema = entry.props.properties?.[key];
      const value = isPlainObject(raw.props) ? raw.props[key] : undefined;
      if (!(entry.props.required ?? []).includes(key)) {
        return false;
      }
      return !schema || !validateValue(value, schema, 0).ok;
    });
    return {
      ok: false,
      reason: failed
        ? `${type}: ${describePropFailure(entry, failed)}`
        : `${type}: props failed validation`,
    };
  }

  const rawChildren = Array.isArray(raw.children) ? raw.children : [];
  const children: UiNode[] = [];

  if (entry.acceptsChildren) {
    if (rawChildren.length > UI_LIMITS.maxChildren) {
      return {
        ok: false,
        reason: `${type} accepts at most ${UI_LIMITS.maxChildren} children`,
      };
    }
    for (const child of rawChildren) {
      const parsed = parseNode(child, depth + 1, state);
      if (!parsed.ok) {
        return parsed;
      }
      children.push(parsed.node);
    }
  }

  return { ok: true, node: { type, props: props.value, children } };
}

export function parseUiSpec(raw: unknown, manifest: UiCatalogManifest): ParseResult {
  return parseNode(raw, 0, {
    entries: catalogIndex(manifest),
    nodes: 0,
  });
}

/** Serializable projection of the catalog sent to the sidecar with each turn. */
export function toManifest(components: UiCatalogEntry[]): UiCatalogManifest {
  return { version: 1, components };
}

/**
 * The closed catalog of surfaces the agent may compose.
 *
 * Two tiers, deliberately small: primitives for composition, cards for the ODI
 * shapes worth naming. Cards are leaves on the wire but render internally with
 * the same primitives, so the agent expresses intent ("score this outcome")
 * rather than layout.
 *
 * This file is the single source of truth. `catalogManifest()` is what travels
 * to the sidecar; `catalogPrompt()` is what the model reads.
 */

import { UI_LIMITS, toManifest, type UiCatalogEntry, type UiPropSchema } from "./protocol";

const actionList: UiPropSchema = {
  type: "array",
  maxItems: UI_LIMITS.maxActions,
  description:
    "Buttons rendered under the surface. Each one sends its `intent` back to you as the user's next message.",
  items: {
    type: "object",
    properties: {
      label: {
        type: "string",
        description: "Short imperative label, two to four words. e.g. \"Simulate this bet\"",
      },
      intent: {
        type: "string",
        description: "The full message to send when clicked, written as the user would say it.",
      },
      tone: { enum: ["primary", "ghost"], description: "Use primary at most once per surface." },
    },
    required: ["label", "intent"],
  },
};

const outcomeScores: Record<string, UiPropSchema> = {
  importance: { type: "number", minimum: 0, maximum: 10 },
  satisfaction: { type: "number", minimum: 0, maximum: 10 },
};

const OPPORTUNITY_TONE: UiPropSchema = {
  enum: ["neutral", "positive", "warning", "critical"],
};

function entry(
  type: string,
  kind: UiCatalogEntry["kind"],
  description: string,
  properties: Record<string, UiPropSchema>,
  required: string[],
  options: { children?: boolean; actions?: boolean } = {},
): UiCatalogEntry {
  const props: Record<string, UiPropSchema> = { ...properties };
  if (options.actions !== false) {
    props.actions = actionList;
  }
  return {
    type,
    kind,
    description,
    acceptsChildren: options.children === true,
    props: {
      type: "object",
      properties: props,
      required,
    },
  };
}

export const CATALOG: readonly UiCatalogEntry[] = [
  // ---------------------------------------------------------------- primitives
  entry(
    "stack",
    "layout",
    "Vertical or horizontal grouping. The default container for anything that is not a card.",
    {
